 const convertDensity=(unit:DensityUnit)=>{try{setDensity(String(fromGcm3(toGcm3(numeric(density,'Density'),densityUnit),unit)));if(densitySigma.trim())setDensitySigma(String(fromGcm3(toGcm3(numeric(densitySigma,'Density uncertainty'),densityUnit),unit)));setExtra(ls=>ls.map(l=>({...l,density:String(fromGcm3(toGcm3(numeric(l.density,'Layer density'),densityUnit),unit))})));}catch{/* validation remains visible */}setDensityUnit(unit);};
 const changeTargetUnit=(unit:TransmissionUnit)=>{try{const f=toFraction(numeric(target,'Target'),targetUnit);setTarget(String(unit==='%'?f*100:f));}catch{/* validation remains visible */}setTargetUnit(unit);};
 const runExport=(kind:'csv'|'pdf')=>{try{if(!a)throw new Error('Resolve input errors before exporting.');const report=buildSnapshot(a,pageNames[page][0]);if(page==='linear'){const k=nonnegative(numeric(direct,'Direct mass coefficient'),'Direct mass coefficient');report.rows.push({section:'Direct converter',name:'User-entered mass coefficient (not NIST lookup)',value:k,unit:'cm2/g'},{section:'Direct converter',name:'Linear result at current primary density',value:linearAttenuation(k,a.input.layers[0].density),unit:'1/cm'});}kind==='csv'?exportCSV(report):exportPDF(report);setExportError('');}catch(e){setExportError(String(e));}};
