function DirectResult({value,density,unit}:{value:string;density:number;unit:LinearUnit}){try{return <output className="direct-result">μ = {nfmt(linearIn(linearAttenuation(nonnegative(numeric(value,'Direct mass coefficient'),'Mass coefficient'),density),unit))} {unit}</output>;}catch(e){return <p role="alert">{String(e)}</p>;}}
function Results({a,page,lang,lengthUnit,linearUnit}:{a:Analysis;page:Page;lang:Language;lengthUnit:LengthUnit;linearUnit:LinearUnit}) {
 const t=(en:string,ar:string)=>lang==='en'?en:ar;
 const len=(v:number|null)=>v===null?'—':nfmt(fromCm(v,lengthUnit));
 const items:Record<string,{label:string;value:string;unit:string;note:string}>={
  mass:{label:t('Mass attenuation','التوهين الكتلي'),value:nfmt(a.coefficient.value),unit:'cm²/g',note:'μ/ρ · '+a.input.source.toUpperCase()},
  linear:{label:t('Linear attenuation','التوهين الخطي'),value:nfmt(linearIn(a.mu,linearUnit)),unit:linearUnit,note:`ρ = ${a.input.layers[0].density} g/cm³`},
  transmission:{label:t('Primary transmission','نفاذ الطبقة الأساسية'),value:a.transmission.transmissionText,unit:'fraction',note:`log₁₀ T = ${nfmt(a.transmission.log10Transmission)}`},
  stack:{label:t('Stack transmission','نفاذ الدرع الكامل'),value:a.stack.total.transmissionText,unit:'fraction',note:`${a.input.layers.length} ${t('layers','طبقات')} · log₁₀ T = ${nfmt(a.stack.total.log10Transmission)}`},
  stackOutput:{label:t('Uncollided stack output','الخرج غير المتصادم للدرع الكامل'),value:a.stackOutput.outputText,unit:t('input photon units','وحدة الفوتونات المُدخلة'),note:'I₀ = '+nfmt(a.input.intensity)},
  hvl:{label:t('Half-value layer','طبقة نصف القيمة'),value:len(a.hvlCm),unit:lengthUnit,note:t('Primary, monoenergetic · T = 0.5','أساسية، أحادية الطاقة · T = 0.5')},
  tvl:{label:t('Tenth-value layer','طبقة عُشر القيمة'),value:len(a.tvlCm),unit:lengthUnit,note:t('Primary, monoenergetic · T = 0.1','أساسية، أحادية الطاقة · T = 0.1')},
  mfp:{label:t('Mean free path','متوسط المسار الحر'),value:len(a.meanFreePath.lengthCm),unit:lengthUnit,note:t('Mean distance to first interaction','متوسط المسافة لأول تفاعل')},
  thickness:{label:t('Required primary thickness','سمك الطبقة الأساسية المطلوب'),value:len(a.requiredThicknessCm),unit:lengthUnit,note:`Ttarget = ${nfmt(a.input.target)}`},
  output:{label:t('Uncollided primary output','الخرج غير المتصادم للطبقة الأساسية'),value:a.transmission.outputText,unit:t('input photon units','وحدة الفوتونات المُدخلة'),note:'I₀ = '+nfmt(a.input.intensity)},
  removal:{label:t('Primary attenuation fraction','الجزء الموهن في الطبقة الأساسية'),value:nfmt(100*a.transmission.attenuationFraction),unit:'%',note:t('Includes scattering out of beam; not absorbed energy','يشمل التشتت خارج الحزمة، وليس الطاقة الممتصة')},
  factor:{label:t('Attenuation factor','عامل التوهين'),value:a.transmission.factorText,unit:'I₀ / I',note:t('Primary material','للمادة الأساسية')},
  targetFactor:{label:t('Target attenuation factor','عامل التوهين المطلوب'),value:scientificFromLog(-Math.log(a.input.target)),unit:'1 / Ttarget',note:t('Specified target, not the current thickness','الهدف المحدد، وليس السمك الحالي')},
  probability:{label:t('First interaction within x','أول تفاعل قبل المسافة x'),value:nfmt(a.meanFreePath.firstInteractionProbability),unit:'probability',note:`x = ${nfmt(a.input.layers[0].thicknessCm)} cm`},
 };
 const which:Record<string,string[]>={complete:['stack','stackOutput','linear','hvl','tvl','mfp','thickness','targetFactor'],mass:['mass'],linear:['mass','linear'],transmission:['transmission','output','removal','factor'],thickness:['thickness','linear','targetFactor'],hvl:['hvl','linear'],tvl:['tvl','hvl','linear'],multilayer:['stack','stackOutput'],mfp:['mfp','probability','linear'],interactions:[],spectrum:[]};
 return <>
  {a.spectrum&&<div className="metrics-grid"><Metric label={t('Photon fluence ratio','نسبة فيض الفوتونات')} value={a.spectrum.photonRatioText} unit="fraction" note="ΣwT / Σw"/><Metric label={t('Energy fluence ratio','نسبة فيض الطاقة')} value={a.spectrum.energyRatioText} unit="fraction" note="ΣEwT / ΣEw"/><Metric label={t('Mean photon energy in','متوسط طاقة الفوتون الداخل')} value={nfmt(a.spectrum.meanInputMeV)} unit="MeV" note={t('Photon-weighted','موزون بالفوتونات')}/><Metric label={t('Mean photon energy out','متوسط طاقة الفوتون النافذ')} value={nfmt(a.spectrum.meanOutputMeV)} unit="MeV" note={t('Uncollided photons','فوتونات غير متصادمة')}/></div>}
  <div className="metrics-grid">{(which[page]||[]).map(k=><Metric key={k} {...items[k]}/>)}</div>
  {page==='mass'&&a.coefficient.energyAbsorption!==undefined&&<div className="notice">μen/ρ = {nfmt(a.coefficient.energyAbsorption)} cm²/g. {t('Mass energy absorption is a separate coefficient. It is not used in the attenuation exponential and does not yield dose without a suitable field/medium model.','امتصاص الطاقة الكتلي معامل منفصل، لا يُستخدم في أس التوهين ولا يكفي وحده لحساب الجرعة.')}</div>}
  {['complete','multilayer'].includes(page)&&<section className="card table-card"><div className="card-heading"><h3>{t('Layer-by-layer results','نتائج كل طبقة')}</h3><span className="badge">{a.input.source.toUpperCase()}</span></div><div className="table-scroll"><table><thead><tr>{[t('Material','المادة'),'μ/ρ (cm²/g)',`μ (${linearUnit})`,`x (${lengthUnit})`,t('Layer T','نفاذ الطبقة'),t('Cumulative T','النفاذ التراكمي')].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{a.stack.layers.map((l,i)=><tr key={i}><td>{i+1}. {lang==='en'?getMaterial(l.materialId).name:getMaterial(l.materialId).nameAr}</td><td>{nfmt(l.coefficient.value)}</td><td>{nfmt(linearIn(l.mu,linearUnit))}</td><td>{nfmt(fromCm(l.thicknessCm,lengthUnit))}</td><td>{l.layerTransmission.transmissionText}</td><td>{l.cumulativeTransmission.transmissionText}</td></tr>)}</tbody></table></div><p className="table-note">{t('Order does not change fixed-coefficient uncollided transmission; scattered and secondary contributions can change.','الترتيب لا يغيّر النفاذ غير المتصادم بمعاملات ثابتة، وقد يغيّر الإشعاع المتشتت والثانوي.')}</p></section>}
  {['complete','interactions'].includes(page)&&<section className="card table-card"><div className="card-heading"><h3>{t('Photon interaction contributions','مساهمات تفاعلات الفوتونات')}</h3><span className={`badge ${a.interactions.consistent?'success':'attention'}`}>{t('XCOM sum check','فحص مجموع XCOM')}: {a.interactions.consistent?'PASS':'REVIEW'}</span></div><div className="table-scroll"><table><thead><tr><th>{t('Process','الآلية')}</th><th>μ/ρ (cm²/g)</th><th>{t('Share of partial sum','النسبة من المجموع الجزئي')}</th></tr></thead><tbody>{a.interactions.parts.map(p=><tr key={p.key}><td>{processNames[p.key][lang==='en'?0:1]}</td><td>{p.allowed?nfmt(p.value):t('0 · below/at threshold','0 · عند/دون العتبة')}</td><td><div className="share-cell"><span style={{width:`${p.fraction*100}%`}}/>{nfmt(100*p.fraction)}%</div></td></tr>)}</tbody></table></div><p className="table-note">Σκ = {nfmt(a.interactions.sum)} · XCOM κtotal = {nfmt(a.interactions.tableTotal)} cm²/g · {t('relative residual','الباقي النسبي')} = {nfmt(a.interactions.relativeResidual*100)}%. {t('Diagnostic tolerance','حد التشخيص')} ±{a.interactions.tolerance*100}% ({t('not an uncertainty estimate','ليس تقديرًا لعدم اليقين')}).</p></section>}
  {a.spectrum&&<section className="card table-card"><div className="card-heading"><h3>{t('Transmitted spectrum','الطيف النافذ')}</h3><span className="badge">{a.spectrum.lines.length} {t('active lines','خطوط فعالة')}</span></div><div className="table-scroll"><table><thead><tr><th>Energy (MeV)</th><th>{t('Input photon weight','وزن فوتوني داخل')}</th><th>T(E)</th><th>{t('Output photon weight','وزن فوتوني نافذ')}</th></tr></thead><tbody>{a.spectrum.lines.map(l=><tr key={l.energyMeV}><td>{nfmt(l.energyMeV)}</td><td>{nfmt(l.weight)}</td><td>{l.transmission.transmissionText}</td><td>{l.outputWeightText}</td></tr>)}</tbody></table></div><p className="table-note">{t('Full energy-dependent transport. No mean-energy substitution. Duplicate entries merged:','نقل كامل يعتمد على كل طاقة، دون استبدال الطيف بمتوسط طاقته. الطاقات المكررة المدمجة:')} {a.spectrum.duplicatesMerged}.</p></section>}
 </>;
}
function Metric({label,value,unit,note}:{label:string;value:string;unit:string;note:string}) {return <div className="card metric"><span>{label}</span><output>{value}<small>{unit}</small></output><p>{note}</p></div>;}
